import json,hashlib
for t in ['task_000010_644ab1c2','task_000118_3043e92d','task_000958_4bb2b05d','task_001031_a8f0eb37','task_001032_1adaccb9','task_001321_658ce4a8']:
    msgs=json.load(open(t+'.messages.json'))
    # extract bash commands from assistant tool_calls -- but format is role tool/assistant. Get tool call args
    cmds=[]
    for m in msgs:
        if m.get('role')=='assistant':
            tcs=m.get('tool_calls') or []
            for tc in tcs:
                fn=tc.get('function',{}) if isinstance(tc,dict) else {}
                args=fn.get('arguments','')
                cmds.append(hashlib.sha256(str(args).encode()).hexdigest()[:8])
    # count max consecutive identical
    mx=0;cur=1
    for i in range(1,len(cmds)):
        if cmds[i]==cmds[i-1]: cur+=1; mx=max(mx,cur)
        else: cur=1
    from collections import Counter
    c=Counter(cmds)
    print(t,'ncalls',len(cmds),'max_consec',mx if cmds else 0,'top_repeat',c.most_common(1)[0] if cmds else None)
"

